INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 4, 'theory', 'Quiz: numbers in a computer');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 4, 0, 'How many bits correspond to one hexadecimal digit?', '["Two", "Four", "Eight", "Sixteen"]', 1, 'A digit 0–F is 16 values, which is exactly 4 bits; a byte is written with two digits.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 4, 1, 'How do you write −5 in eight bits using two''s complement?', '["10000101", "11111010", "11111011", "00000101"]', 2, 'Invert 00000101 → 11111010 and add 1 → 11111011 (251 as unsigned).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 4, 2, 'What is the range of a signed 8-bit number in two''s complement?', '["from −127 to 127", "from −128 to 127", "from −255 to 255", "from 0 to 255"]', 1, 'There is only one zero, so there is one more negative value: from −128 to 127.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 4, 3, 'Why does the comparison 0.1 + 0.2 == 0.3 give “false” with floating-point numbers?', '["It is a language bug", "0.1 and 0.2 are infinite fractions in binary and are stored with an error", "Adding floating-point numbers is forbidden", "The result is an integer"]', 1, 'Decimal fractions like 0.1 cannot be represented exactly in binary; you have to compare with a tolerance.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 4, 4, 'In what order is 0x12345678 stored in memory on a little-endian processor?', '["12 34 56 78", "78 56 34 12", "21 43 65 87", "87 65 43 21"]', 1, 'Little-endian: the least significant byte comes first — 78 56 34 12; in network order (big-endian) it is 12 34 56 78.');
